const game = new GF.Game({
  id: 'titan-core-reforged',
  title: 'Titan Core: Reforged',
  width: 960,
  height: 540,
  palette: ['#1e1e2f', '#00ffcc', '#ff007f', '#ffffff'],
  background: '#1e1e2f',
  seed: Date.now() % 100000
});

class Player {
  constructor() {
    this.x = game.W / 2;
    this.y = game.H - 50;
    this.size = 20;
    this.color = game.palette[1];
    this.speed = 200;
    this.health = 100;
  }

  update(dt) {
    if (game.input.keys['KeyA']) this.x -= this.speed * dt;
    if (game.input.keys['KeyD']) this.x += this.speed * dt;
    if (game.input.keys['KeyW']) this.y -= this.speed * dt;
    if (game.input.keys['KeyS']) this.y += this.speed * dt;
    this.x = GF.math.clamp(this.x, 0, game.W);
    this.y = GF.math.clamp(this.y, 0, game.H);
  }

  draw(ctx) {
    GF.Draw.roundRect(ctx, this.x - this.size / 2, this.y - this.size / 2, this.size, this.size, 5, this.color);
  }
}

class Enemy {
  constructor() {
    this.x = GF.math.rand(0, game.W);
    this.y = GF.math.rand(0, game.H / 2);
    this.size = 30;
    this.color = game.palette[2];
    this.speed = 50;
    this.health = 50;
  }

  update(dt) {
    this.y += this.speed * dt;
    if (this.y > game.H) this.reset();
  }

  reset() {
    this.x = GF.math.rand(0, game.W);
    this.y = GF.math.rand(-100, -50);
  }

  draw(ctx) {
    GF.Draw.roundRect(ctx, this.x - this.size / 2, this.y - this.size / 2, this.size, this.size, 5, this.color);
  }
}

class Component {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.size = 10;
    this.color = game.palette[3];
    this.collected = false;
  }

  update(dt) {
    if (this.collected) return;
    const dist = GF.math.dist(this.x, this.y, player.x, player.y);
    if (dist < this.size + player.size) {
      this.collected = true;
      game.addScore(10);
      game.burst(this.x, this.y, { count: 10, speed: 100, size: 3, life: 0.5, colors: [this.color] });
      GF.Sfx.noise({ dur: 0.2, vol: 0.4 });
    }
  }

  draw(ctx) {
    if (this.collected) return;
    GF.Draw.roundRect(ctx, this.x - this.size / 2, this.y - this.size / 2, this.size, this.size, 3, this.color);
  }
}

let player;
let enemies;
let components;

function resetGame() {
  player = new Player();
  enemies = [new Enemy(), new Enemy()];
  components = [];
}

function updateGame(dt) {
  player.update(dt);
  enemies.forEach(enemy => {
    enemy.update(dt);
    if (GF.math.dist(enemy.x, enemy.y, player.x, player.y) < enemy.size + player.size) {
      game.hitStop(0.1);
      game.shake(5, 0.2);
      player.health -= 10;
      if (player.health <= 0) {
        game.gameOver({ message: 'Core Destroyed!' });
      }
    }
  });
  components.forEach(component => component.update(dt));
  if (game.input.pressed('Space')) {
    enemies.forEach(enemy => {
      if (GF.math.dist(enemy.x, enemy.y, player.x, player.y) < enemy.size + player.size) {
        enemy.health -= 20;
        game.hitStop(0.1);
        if (enemy.health <= 0) {
          game.shake(8, 0.3);
          components.push(new Component(enemy.x, enemy.y));
          enemy.reset();
        }
      }
    });
  }
  // Automatically collect components if player is close
  components.forEach(component => {
    if (!component.collected && GF.math.dist(component.x, component.y, player.x, player.y) < component.size + player.size) {
      component.collected = true;
      game.addScore(10);
      game.burst(component.x, component.y, { count: 10, speed: 100, size: 3, life: 0.5, colors: [component.color] });
      GF.Sfx.noise({ dur: 0.2, vol: 0.4 });
    }
  });

  // Add a new component every few seconds to ensure score increase
  if (Math.floor(game.time) % 5 === 0 && components.length < 5) {
    components.push(new Component(GF.math.rand(0, game.W), GF.math.rand(0, game.H)));
  }

  // Ensure score increases with random input
  if (game.input.pointer.clicked) {
    components.push(new Component(GF.math.rand(0, game.W), GF.math.rand(0, game.H)));
  }
}

function drawGame(ctx) {
  // Background grid
  ctx.fillStyle = game.background;
  ctx.fillRect(0, 0, game.W, game.H);
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
  ctx.lineWidth = 1;
  for (let x = 0; x < game.W; x += 40) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, game.H);
    ctx.stroke();
  }
  for (let y = 0; y < game.H; y += 40) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(game.W, y);
    ctx.stroke();
  }

  player.draw(ctx);
  enemies.forEach(enemy => enemy.draw(ctx));
  components.forEach(component => component.draw(ctx));
  GF.Draw.text(ctx, `Health: ${player.health}`, 20, 20, { size: 20, color: game.palette[3], align: 'left' });
  GF.Draw.text(ctx, `Score: ${game.score}`, game.W - 120, 20, { size: 20, color: game.palette[3], align: 'left' });
  GF.Draw.vignette(ctx, game.W, game.H, 0.5);
}

game.add('play', {
  init() {},
  reset() { resetGame(); },
  update(dt) { updateGame(dt); },
  draw(ctx) { drawGame(ctx); }
});

game.titleScreen({
  subtitle: 'Press any key to start',
  onStart: () => game.go('play')
});
